NAME = 'CebPinadayag: Cebuano Pinadayag'
BOOK = 'Habakkuk'

CHAPTERS = {
    1: {
        1: 'Ang palas-anon nga nakita ni Habacuc nga manalagna.',
        2: 'Oh Jehova, hangtud anus-a ang akong pagtu-aw, ug ikaw dili mamati kanako? Ako nagatu-aw kanimo tungod sa pagpanlupig nga nahimo, ug ikaw dili moluwas kanako.',
        3: 'Ngano nga gipakita mo kanako ang kasal-anan, ug nagatan-aw ka sa pagkadautan? kay ang pagkalaglag ug ang pagpanlupig ania sa akong atubangan; ug adunay kagubot, ug mitindog ang pagkabingkil.',
        4: 'Busa ang Kasugoan walay gahum, ang justicia wala gayud magapadayon; kay ang dautan nagalibut sa matarung: busa ang justicia nagapadayon nga binalit-ad.',
        5: 'Tuman-aw kamo sa taliwala sa mga nasud, ug sud-onga ninyo, ug managkatingala sa dakung kahibulong; kay ako nagabuhat sa usa ka dakung bulohaton sa inyong mga adlaw, nga dili ninyo katuhoan, bisan pa kini ginasugilon kaninyo.',
        6: 'Kay, ania karon, akong bangonon ang mga Caldeahanon, kanang mapait ug madali-dalion nga nasud, nga nagasuroy sa kinalapdan sa kalibutan, aron sa pagpanag-iya sa mga puloy-anan nga dili man unta ila.',
        7: 'Sila makahahadlok ug makalilisang; ang ilang paghukom ug ang ilang pagkahalangdon nagagikan sa ilang kaugalingon.',
        8: 'Ang ilang mga kabayo usab matulin pa kay sa mga leopardo, ug labing mabangis kay sa mga lobo sa kagabhion; ug, ang ilang mga magkakabayo nanagpadayon nga mapahitas-on: oo, ang ilang mga magkakabayo nagagikan sa halayo; sila nagalupad ingon sa agila nga nagadali aron sa paglamoy.',
        9: 'Sila nangabut ang tanan kanila aron sa pagpanlupig; ilang gipahamutang ang dulong sa ilang mga nawong paingon sa unahan; ug sila nagatigum ug mga binihag ingon sa bonbon.',
        10: 'Oo, iyang gibugalbugalan ang mga hari, ug ang mga principe mga kataw-hanan lamang alang kaniya; iyang gikataw-an ang tanang mga kuta; kay siya nagatapok ug abug, ug iyang ginaagaw kini:',
        11: 'Unya siya mohuros ingon sa hangin, ug mosaylo sa ibabaw, ug mahimong sad-an, kadto siya kansang gahum mao ang iyang dios.',
        12: 'Dili ba ikaw gikan sa walay katapusan, Oh Jehova nga akong Dios, ang akong Balaan? kami dili mamatay, Oh Jehova, imong gitudlo siya aron sa paghukom kaniya; ug ikaw, Oh Bato namo, imo siyang gitukod aron sa pagsaway kanila.',
        13: 'Ikaw man ang may labing maputling mga mata kay sa pagtan-aw sa kadautan, ug ikaw nga dili makatan-aw sa pagkamasupilon, ngano man nga nagatan-aw ikaw kanila nga nagabuhat sa pagkamabudhion, ug nagahilum ka sa diha nga ang tawong dautan nagalamoy sa tawo nga labing matarung kay kaniya:',
        14: 'Ug nagahimo sa mga tawo nga maingon sa mga isda sa dagat, maingon sa mga butang nga nanagkamang, nga walay nagadumala kanila?',
        15: 'Iyang gikuha sila ngatanan pinaagi sa taga, iyang gisikup sila sa iyang pukot, ug sila gitigum niya sa iyang tapsay; busa siya nagamaya ug nagamalipayon.',
        16: 'Busa nagahalad siya alang sa iyang pukot, ug nagasunog incienso alang sa iyang tapsay; kay pinaagi kanila ang iyang bahin matambok ug daghan ang iyang makaon.',
        17: 'Iyabyab ba diay niya ang iyang pukot, ug dili pagsayloan sa pagpatay nga dayon ang mga nasud?',
    },
    2: {
        1: 'Ako motindog sa akong bantayan, ug mopahaluna ako ibabaw sa lantawan, ug molantaw ako sa pagtan-aw kong unsa ang iyang igasulti kanako, ug kong unsa ang akong igatubag mahatungod sa akong sumbong.',
        2: 'Ug si Jehova mitubag kanako, ug miingon: Isulat ang panan-awon, ug himoang matin-aw diha sa mga sulatanan, aron modalagan kadtong magabasa niini.',
        3: 'Kay ang panan-awon alang pa sa natudlong panahon, ug kini nagadali paingon sa katapusan, ug dili magbakak; bisan kini malangan, paabuta kini; kay kini moabut gayud, kini dili magalangan.',
        4: 'Ania karon, ang iyang kalag nagapaburot; kini dili matarung diha kaniya; apan ang matarung mabuhi tungod sa iyang pagtoo.',
        5: 'Oo, labut pa, ang vino mabudhion, tawo nga mapahitas-on, nga dili mopabilin sa iyang balay; nga nagapadaku sa iyang tinguha maingon sa Sheol, ug siya maingon sa kamatayon, ug dili matagbaw, apan nagatigum sa mga nasud ngadto kaniya, ug nagatapok sa mga katawohan ngadto kaniya.',
        6: 'Dili ba kining tanan mohisgut usa ka sambingay batok kaniya, ug sa usa ka mabiaybiayon nga sanglitanan batok kaniya, ug magaingon: Alaut siya nga nagapatubo niadtong dili iya! hangtud anus-a kana? ug kadtong nagalulan sa iyang kaugalingon tungod sa mga prenda nga inagaw!',
        7: 'Sila dili ba manindog sa dihadiha kadtong mopaak kanimo, ug dili ba mahigmata kadtong magasamok kanimo, ug ikaw mahimong tinikas alang kanila?',
        8: 'Tungod kay imong gitulis ang daghang mga nasud, ang tanang nanghibilin sa mga katawohan magatulis kanimo, tungod sa giula nga dugo sa mga tawo, ug sa pagpanlupig nga nahimo diha sa yuta, sa ciudad, ug sa tanang nanagpuyo diha.',
        9: 'Alaut kadtong nagakuha ug dautang abut alang sa iyang balay, aron ikapahamutang niya ang iyang salag sa itaas, aron maluwas siya gikan sa kamot sa dautan.',
        10: 'Ikaw nagmugna ug kaulaw sa imong balay pinaagi sa paglaglag sa daghanang katawohan, ug nakasala ka batok sa imong kalag.',
        11: 'Kay ang bato mosinggit sa Dios gikan sa kuta, ug ang sagbayan motubag niana gikan sa tigkahoy.',
        12: 'Alaut kadtong nagatukod sa usa ka lungsod pinaagi sa pag-ula sa dugo, ug nagapatindog sa usa ka ciudad pinaagi sa kasal-anan!',
        13: 'Ania karon, dili ba gikan kang Jehova sa mga panon nga ang katawohan nagabuhat alang sa kalayo, ug ang mga nasud nagabudlay sa ilang kaugalingon alang sa kakawangan?',
        14: 'Kay ang kalibutan pagapun-on sa ihibalo sa himaya ni Jehova, maingon nga ang katubigan nagatabon sa dagat.',
        15: 'Alaut kadtong nagapainum sa makahubog sa iyang isigkatawo, kanimo nga nagadugang sa imong hilo, ug nagapahubog kaniya usab, aron ikaw makasud-ong sa ilang pagkahubo!',
        16: 'Ikaw nabuhong na sa kaulaw ug dili sa himaya: uminum ka usab, ug manig-ingon ka sa usa nga walay-circuncicion; ang copa sa kamot nga too ni Jehova moanha kanimo, ug ang mahugaw nga kaulaw magatabon sa imong himaya.',
        17: 'Kay ang kadaut nga gihimo sa Libano magaputos kanimo, ug ang pagkalaglag sa mga mananap, nga nakapahadlok kanila; tungod sa giula nga dugo sa tawo, ug sa pagpanlupig nga gihimo diha sa yuta, sa ciudad, ug sa tanang nanagpuyo diha.',
        18: 'Unsa ang kapuslanan sa linilok nga larawan, nga gililok sa nagabuhat niana; ingon man ang tinunaw nga larawan, bisan pa ang magtutudlo sa kabakakan, sa pagkaagi nga kadtong nagahimo sa iyang dagway nagasalig man niana, aron sa paghimo nga amang sa mga larawan?',
        19: 'Alaut siya nga nagaingon sa kahoy: Pagmata na; ug sa amang nga bato: Tumindog ka! Makatudlo ba kini? Ania karon, kini gihal-opan sa bulawan ug salapi, ug sa sulod niana wala gayud ing gininhawa.',
        20: 'Apan si Jehova ania sa iyang balaan nga templo: pahiluma sa atubangan niya ang tibook nga kalibutan.',
    },
    3: {
        1: 'Ang pag-ampo ni Habacuc nga manalagna, gihimo pinaagi sa Sigionoth.',
        2: 'Oh Jehova, nabati ko ang balita mahitungod kanimo, ug ako nahadlok: Oh Jehova, buhia ang imong buhat sa taliwala sa katuigan; Sa taliwala sa katuigan ipahibalo kini; Sa kaligutgut hinumdumi ang kalooy.',
        3: 'Ang Dios mianhi gikan sa Teman, Ug ang Balaan gikan sa bukid sa Paran (Selah Ang iyang himaya milukop sa kalangitan, Ug ang yuta napuno sa pagdayeg kaniya.',
        4: 'Ug ang iyang kahayag maingon sa suga; Siya adunay mga kasilaw nga nagagikan sa iyang kamot; Ug didto gitagoan ang iyang kagahum.',
        5: 'Kaniya nagauna ang kamatay, ug ang mga baga minggula didto sa iyang mga tiil.',
        6: 'Mitindog siya ug gisukod ang yuta; Mitan-aw siya, ug gibulagbulag ang mga nasud; Ug gipanagkatag ang walay-katapusan nga kabukiran; Nangaunlod ang mga bungtod nga walay katapusan; Ang iyang mga paglakaw maingon man sa kanhing panahon.',
        7: 'Nakita ko ang mga balong-balong sa Cushan nga diha sa kagulanan; Nangurog ang mga tabil sa yuta sa Madian.',
        8: 'Gikayugtan ba ni Jehova ang mga suba, Nasuko ba ikaw batok sa mga suba, Kun batok ba sa dagat ang imong kaligutgut, Nga nagkabayo man ikaw sa imong mga kabayo, Sa imong mga carro sa kaluwasan?',
        9: 'Ang imong pana gihimo nga walay putos; Ang mga panumpa sa kabanayan maoy pulong nga matuod. (Selah. Imong gibahin ang yuta pinaagi sa mga suba.',
        10: 'Nanagpakakita kanimo ang kabukiran, ug nangahadlok; Miagi ang unos sa kadagatan; Nagpagula sa iyang tingog ang kahiladman, Ug gibayaw ang iyang mga kamot sa itaas.',
        11: 'Ang adlaw ug ang bulan ming-urong sa walay paglihok sa ilang pinuy-anan, Sa kahayag sa imong mga udyong samtang sila nanagpanaw, Sa kasanag sa imong masidlakong bangkaw.',
        12: 'Milatas ka sa kasuko sa yuta; Gigiukan mo tungod sa kasuko ang mga nasud.',
        13: 'Mipanaw ka alang sa kaluwasan sa imong katawohan, Alang sa kaluwasan sa imong dinihog; Gisamaran mo ang ulo gikan sa balay sa dautang tawo, Ginaablihan ang patukoranan bisan hangtud sa liog. (Selah.',
        14: 'Gipalagbasan mo sa iyang kaugalingong mga bangkaw ang ulo sa iyang mga manggugubat: Ming-anhi sila ingon sa bagyo sa pagkatag kanako; Ang ilang panagmaya sama niadtong molamoy sa kabus sa tago nga dapit.',
        15: 'Imong gipayatakan ang dagat sa imong mga kabayo, Ang gantong sa gamhanan nga mga tubig.',
        16: 'Nakabati ako, ug mikurog ang akong lawas, Nangurog ang akong mga ngabil sa tingog; Misulod sa akong kabukogan ang kadunotan, ug mikurog ako sa akong himutangan; Kay sa hilum kinahanglan maga-hulat ako sa adlaw sa kasamok, Alang sa pag-abut sa katawohan nga mosulong kanamo.',
        17: 'Kay bisan ang kahoyng higuera dili molambo, Ni may mga bunga diha sa mga balagon; Ang buhat sa olivo makawang, Ug ang kaumahan dili mohatag sa makaon; Ang mga carnero, pagalaglagon gi-kan sa mga toril, Ug didto walay mga panon sa vaca sulod sa mga kamalig:',
        18: 'Bisan pa niana magamaya ako diha kang Jehova, Magamalipayon ako sa Dios sa akong kaluwasan.',
        19: 'Si Jehova, nga Ginoo, mao ang akong kalig-on; Ug ang akong mga tiil himoon niya nga sama sa mga tiil sa mga bayeng lagsaw, Ug palakton ako niya sa mga hatag-as nakong dapit.',
    },
}
